"use strict";(self.webpackChunkimport_ean_upc_barcodes_doc=self.webpackChunkimport_ean_upc_barcodes_doc||[]).push([[905],{9509(e,i,n){n.r(i),n.d(i,{comp:()=>a,data:()=>s});var t=n(641);const l=[(0,t.Fv)('<h1 id="installation" tabindex="-1"><a class="header-anchor" href="#installation"><span>Installation</span></a></h1><p>Installing the <strong>Import EAN UPC Barcodes</strong> plugin follows the standard WordPress plugin installation process.</p><h2 id="requirements" tabindex="-1"><a class="header-anchor" href="#requirements"><span>Requirements</span></a></h2><p>Before you install the plugin, ensure your server meets the following minimum requirements:</p><ul><li><strong>WordPress</strong>: Version 6.5 or higher (Tested up to 6.8)</li><li><strong>WooCommerce</strong>: Version 9.1 or higher (Tested up to 10.4)</li><li><strong>PHP</strong>: 7.4 or higher (8.0+ recommended for best performance)</li></ul><h2 id="uploading-the-plugin" tabindex="-1"><a class="header-anchor" href="#uploading-the-plugin"><span>Uploading the Plugin</span></a></h2><ol><li><p>Purchase and download the plugin zip file from the Webkul store.</p></li><li><p>Log into your WordPress Admin Dashboard.</p></li><li><p>Navigate to <strong>Plugins &gt; Add New Plugin</strong> in the left-hand sidebar. <img src="/import-ean-upc-barcodes/images/guide/installation-add-new.webp" alt="Access Plugin Upload"></p></li><li><p>Click the <strong>Upload Plugin</strong> button at the top of the page.</p></li><li><p>Click <strong>Choose File</strong> and select the <code>import-ean-upc-barcodes.zip</code> file you downloaded. <img src="/import-ean-upc-barcodes/images/guide/installation-upload-plugin.webp" alt="Upload Plugin Archive"></p></li><li><p>Click <strong>Install Now</strong>.</p></li></ol><h2 id="activation" tabindex="-1"><a class="header-anchor" href="#activation"><span>Activation</span></a></h2><ol><li><p>Once the installation is complete, click the <strong>Activate Plugin</strong> button. <img src="/import-ean-upc-barcodes/images/guide/installation-activate-plugin.webp" alt="Activate Plugin"></p></li><li><p>Upon successful activation, a new menu item will appear in your WordPress sidebar under <strong>Webkul WC Addons &gt; UPC/EAN Codes</strong>.</p></li></ol><blockquote><p>[!TIP] <strong>Locating the Menu</strong> The plugin settings and import tools are consolidated under a single menu. Look for <strong>Webkul WC Addons</strong> in your admin sidebar, then click on <strong>UPC/EAN Codes</strong>.</p></blockquote><h2 id="license-verification" tabindex="-1"><a class="header-anchor" href="#license-verification"><span>License Verification</span></a></h2><p>To access the plugin features, you may need to verify your purchase license.</p><ol><li>Navigate to <strong>Webkul WC Addons &gt; License</strong>.</li><li>Enter your purchase code or license details provided at the time of purchase.</li><li>Save the changes to fully unlock the plugin.</li></ol>',13)],o={},a=(0,n(6262).A)(o,[["render",function(e,i){return(0,t.uX)(),(0,t.CE)("div",null,l)}]]),s=JSON.parse('{"path":"/guide/installation.html","title":"Installation","lang":"en-US","frontmatter":{"title":"Installation"},"headers":[{"level":2,"title":"Requirements","slug":"requirements","link":"#requirements","children":[]},{"level":2,"title":"Uploading the Plugin","slug":"uploading-the-plugin","link":"#uploading-the-plugin","children":[]},{"level":2,"title":"Activation","slug":"activation","link":"#activation","children":[]},{"level":2,"title":"License Verification","slug":"license-verification","link":"#license-verification","children":[]}],"git":{},"filePathRelative":"guide/installation.md"}')}}]);